// O DJEN busca pelo número CNJ formatado (com pontos e traço). O GET do CRM
// devolve só os dígitos em `numero` e o texto original em `numeroNaTabela`,
// que pode ter anotação junto — por isso o número é remontado a partir dos
// dígitos, garantindo o formato exato que a API espera.
return $input.all().map(item => {
  const d = String(item.json.numero || '').replace(/\D/g, '');
  const formatado = d.length === 20
    ? `${d.slice(0, 7)}-${d.slice(7, 9)}.${d.slice(9, 13)}.${d.slice(13, 14)}.${d.slice(14, 16)}.${d.slice(16)}`
    : null;

  return {
    json: {
      rowId: item.json.rowId,
      numero: formatado || item.json.numeroNaTabela || item.json.numero,
      numeroFormatado: formatado,
      valido: !!formatado
    }
  };
});

// Empacota TODAS as publicações de cada processo para o CRM.
//
// Antes este nó escolhia só a mais recente. Como a central de novidades quer
// uma linha por comunicação, agora vai a lista inteira: o CRM deduplica pelo
// `id`/`hash` que o próprio DJEN manda, então reenviar é inofensivo.
//
// ARMADILHA QUE ESTE NÓ RESOLVE: quando o CNJ responde 429, a ponte devolve
// `{error, status_origem}` — um corpo sem `items`. Tratar isso como lista
// vazia classificaria o processo como "sem publicação" e o falso negativo
// passaria batido. Erro agora é erro, e sai separado do vazio legítimo.
const saida = [];
const entradas = $input.all();

for (let i = 0; i < entradas.length; i++) {
  let origem = {};
  try { origem = $('Preparar consulta DJEN').itemMatching(i).json; } catch (e) { origem = {}; }

  const corpo = entradas[i].json || {};
  const numero = origem.numero || null;

  if (corpo.error || corpo.status_origem) {
    saida.push({ json: { numero, rowId: origem.rowId, falhou: true, erro: String(corpo.error || '').slice(0, 200) } });
    continue;
  }

  const itens = Array.isArray(corpo.items) ? corpo.items : [];
  saida.push({
    json: {
      numero,
      rowId: origem.rowId,
      falhou: false,
      total: itens.length,
      // itens crus: o CRM precisa de id, hash, destinatarioadvogados, ativo etc.
      publicacoes: itens
    }
  });
}

return saida;

// Consolida a execução. Quem decide se houve mudança é o CRM.
const itens = $input.all().map(i => i.json || {});
const conta = s => itens.filter(i => i.status === s).length;
const somaIngestao = itens.reduce((n, i) => n + (i?.ingestao?.inseridas || 0), 0);

return [{
  json: {
    quando: new Date().toISOString(),
    fonte: 'DJEN / Comunica (CNJ)',
    processados: itens.length,
    comunicacoes_novas: somaIngestao,
    previa_atualizada: conta('atualizado'),
    sem_mudanca: conta('sem_mudanca'),
    sem_publicacao: conta('sem_publicacao'),
    nao_encontrados_no_crm: conta('nao_encontrado'),
    com_erro: itens.filter(i => i.error).length
  }
}];

// Consulta que NÃO funcionou (timeout, 429 do CNJ, ponte fora do ar).
// Fica separado do "sem publicação" de propósito: aqui não se sabe se havia
// publicação, então tratar como vazio criaria falso negativo silencioso.
const itens = $input.all().map(i => i.json || {});
return [{
  json: {
    tipo: 'consulta ao DJEN falhou — reprocessar',
    quantidade: itens.length,
    numeros: itens.map(i => i.numero),
    exemplos_de_erro: [...new Set(itens.map(i => i.erro).filter(Boolean))].slice(0, 5)
  }
}];
